const listWorkflows = `-- name: ListWorkflows :many
SELECT id, workspace_id, key, name, description, status, latest_version, revision, created_by_type, created_by_id, created_at, updated_at FROM workflow
WHERE workspace_id = $1::uuid
  AND ($2::bool OR status = 'active')
ORDER BY LOWER(name) ASC, key ASC
`

type ListWorkflowsParams struct {
	WorkspaceID     pgtype.UUID `json:"workspace_id"`
	IncludeArchived bool        `json:"include_archived"`
}

// Every member may read; whether a workflow can be edited is a handler
// decision. LOWER(name) keeps the order stable across equal names.
func (q *Queries) ListWorkflows(ctx context.Context, arg ListWorkflowsParams) ([]Workflow, error) {
	rows, err := q.db.Query(ctx, listWorkflows, arg.WorkspaceID, arg.IncludeArchived)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Workflow{}
	for rows.Next() {
		var i Workflow
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.Key,
			&i.Name,
			&i.Description,
			&i.Status,
			&i.LatestVersion,
			&i.Revision,
			&i.CreatedByType,
			&i.CreatedByID,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const setWorkflowLatestVersion = `-- name: SetWorkflowLatestVersion :one
UPDATE workflow SET
    latest_version = $1::int,
    revision = revision + 1,
    updated_at = now()
WHERE id = $2::uuid AND workspace_id = $3::uuid
RETURNING id, workspace_id, key, name, description, status, latest_version, revision, created_by_type, created_by_id, created_at, updated_at
`

type SetWorkflowLatestVersionParams struct {
	LatestVersion int32       `json:"latest_version"`
	ID            pgtype.UUID `json:"id"`
	WorkspaceID   pgtype.UUID `json:"workspace_id"`
}

// Called inside the transaction that inserted the version, under the row lock
// from GetWorkflowForUpdate.
func (q *Queries) SetWorkflowLatestVersion(ctx context.Context, arg SetWorkflowLatestVersionParams) (Workflow, error) {
	row := q.db.QueryRow(ctx, setWorkflowLatestVersion, arg.LatestVersion, arg.ID, arg.WorkspaceID)
	var i Workflow
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.Key,
		&i.Name,
		&i.Description,
		&i.Status,
		&i.LatestVersion,
		&i.Revision,
		&i.CreatedByType,
		&i.CreatedByID,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const updateWorkflowDetails = `-- name: UpdateWorkflowDetails :one
UPDATE workflow SET
    name = COALESCE($1, name),
    description = COALESCE($2, description),
    status = COALESCE($3, status),
    revision = revision + 1,
    updated_at = now()
WHERE id = $4::uuid
  AND workspace_id = $5::uuid
  AND revision = $6::bigint
RETURNING id, workspace_id, key, name, description, status, latest_version, revision, created_by_type, created_by_id, created_at, updated_at
`

type UpdateWorkflowDetailsParams struct {
	Name             pgtype.Text `json:"name"`
	Description      pgtype.Text `json:"description"`
	Status           pgtype.Text `json:"status"`
	ID               pgtype.UUID `json:"id"`
	WorkspaceID      pgtype.UUID `json:"workspace_id"`
	ExpectedRevision int64       `json:"expected_revision"`
}

// COALESCE-on-narg partial update of the head. `revision` is the optimistic
// concurrency guard: the caller passes the revision it loaded and gets no row
// back if someone changed the head since.
func (q *Queries) UpdateWorkflowDetails(ctx context.Context, arg UpdateWorkflowDetailsParams) (Workflow, error) {
	row := q.db.QueryRow(ctx, updateWorkflowDetails,
		arg.Name,
		arg.Description,
		arg.Status,
		arg.ID,
		arg.WorkspaceID,
		arg.ExpectedRevision,
	)
	var i Workflow
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.Key,
		&i.Name,
		&i.Description,
		&i.Status,
		&i.LatestVersion,
		&i.Revision,
		&i.CreatedByType,
		&i.CreatedByID,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
